from datetime import datetime
import math


class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = float(hourly_rate)

    def fee(self, entry: datetime, exit: datetime) -> float:
        if exit < entry:
            raise ValueError("Exit time cannot be earlier than entry time.")

        total_seconds = (exit - entry).total_seconds()

        # Stays longer than 24 hours are charged a flat penalty fee
        if total_seconds > 24 * 3600:
            return 200.00

        # Stays of at most 15 minutes are free
        if total_seconds <= 15 * 60:
            return 0.00

        # Calculate proportional hourly fee for the entire duration
        hours = total_seconds / 3600.0
        calculated_fee = hours * self.hourly_rate

        return round(calculated_fee, 2)
